import { FormApi } from '@tanstack/form-core';
import { useStore } from '@tanstack/svelte-store';
import { onMount } from 'svelte';
import Field, { createField } from './Field.svelte';
import Subscribe from './Subscribe.svelte';
export function createForm(opts) {
    const options = opts?.();
    const api = new FormApi(options);
    const extendedApi = api;
    // @ts-expect-error constructor definition exists only on a type level
    extendedApi.Field = (internal, props) => Field(internal, { ...props, form: api });
    extendedApi.createField = (props) => createField(() => {
        return { ...props(), form: api };
    }); // Type cast because else "Error: Type instantiation is excessively deep and possibly infinite."
    extendedApi.useStore = (selector) => useStore(api.store, selector);
    // @ts-expect-error constructor definition exists only on a type level
    extendedApi.Subscribe = (internal, props) => Subscribe(internal, { ...props, store: api.store });
    onMount(api.mount);
    // formApi.update should not have any side effects. Think of it like a `useRef`
    // that we need to keep updated every render with the most up-to-date information.
    $effect.pre(() => api.update(opts?.()));
    return extendedApi;
}
